void dm_crtc_handle_vblank ( struct amdgpu_crtc * acrtc ) { struct drm_crtc * crtc = & acrtc -> base ; struct drm_device * dev = crtc -> dev ; unsigned long flags ; drm_crtc_handle_vblank ( crtc ) ; spin_lock_irqsave ( & dev -> event_lock , flags ) ; if ( acrtc -> event && acrtc -> pflip_status != AMDGPU_FLIP_SUBMITTED ) { drm_crtc_vblank_put ( crtc ) ; acrtc -> event = NULL ; } spin_unlock_irqrestore ( & dev -> event_lock , flags ) ; } 